using System.IO.Compression;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace LiveryStudio.Core;

public static class VehicleProjectBundle
{
    private sealed record Manifest(int Version,Dictionary<string,string> Hashes);
    public static void Save(VehicleAssemblyProject project,string destination)
    {
        project.Validate();var temp=Path.Combine(Path.GetTempPath(),"FLS-car-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);
        var copy=JsonSerializer.Deserialize<VehicleAssemblyProject>(JsonSerializer.Serialize(project,Contract.Json),Contract.Json)!;
        var sources=new Dictionary<string,string>{{"Exterior"+Path.GetExtension(project.ExteriorFile).ToLowerInvariant(),project.ExteriorFile}};
        void Optional(string name,string path){if(File.Exists(path))sources.Add(name,path);}
        Optional("Assembly.FBX",project.AssemblyFile);Optional("Layout.tsv",project.BindingFile);Optional("Report.json",project.ReportFile);Optional("Preview.flsm",project.PreviewFile);
        var paint=Path.Combine(temp,"Paint.flproject");ProjectBundle.Save(project.Paint,paint);sources.Add("Paint.flproject",paint);
        copy.ExteriorFile=sources.Keys.Single(n=>n.StartsWith("Exterior",StringComparison.Ordinal));copy.AssemblyFile=sources.ContainsKey("Assembly.FBX")?"Assembly.FBX":"";copy.BindingFile=sources.ContainsKey("Layout.tsv")?"Layout.tsv":"";copy.ReportFile=sources.ContainsKey("Report.json")?"Report.json":"";copy.PreviewFile=sources.ContainsKey("Preview.flsm")?"Preview.flsm":"";copy.Paint=new(){CarIndex=project.DonorIndex,IndependentPaintSides=project.Paint.IndependentPaintSides,FlatExteriorNormals=!project.Paint.IndependentPaintSides};
        if(copy.PreparedDesign.Length>0){var old=JsonSerializer.Deserialize<VehicleAssemblyProject>(copy.PreparedDesign,Contract.Json)??throw new InvalidDataException("Invalid previous car recipe.");old.PreparedDesign="";old.ExteriorFile=copy.ExteriorFile;old.AssemblyFile=copy.AssemblyFile;old.BindingFile=copy.BindingFile;old.ReportFile=copy.ReportFile;old.PreviewFile=copy.PreviewFile;old.Paint=new(){CarIndex=old.DonorIndex,IndependentPaintSides=project.Paint.IndependentPaintSides,FlatExteriorNormals=!project.Paint.IndependentPaintSides};copy.PreparedDesign=JsonSerializer.Serialize(old,Contract.Json);}
        var recipe=Path.Combine(temp,"Car.json");File.WriteAllText(recipe,JsonSerializer.Serialize(copy,Contract.Json));sources.Add("Car.json",recipe);
        var hashes=sources.ToDictionary(s=>s.Key,s=>WorkshopService.Hash(s.Value),StringComparer.Ordinal);var output=Path.GetFullPath(destination);Directory.CreateDirectory(Path.GetDirectoryName(output)!);var partial=output+"."+Guid.NewGuid().ToString("N")+".tmp";
        try{using(var archive=ZipFile.Open(partial,ZipArchiveMode.Create)){foreach(var source in sources)archive.CreateEntryFromFile(source.Value,source.Key,CompressionLevel.Optimal);using var writer=new StreamWriter(archive.CreateEntry("Manifest.json").Open());writer.Write(JsonSerializer.Serialize(new Manifest(1,hashes),Contract.Json));}File.Move(partial,output,true);}finally{if(File.Exists(partial))File.Delete(partial);}
    }
    public static VehicleAssemblyProject Open(string path,string workspace)
    {
        using var archive=ZipFile.OpenRead(path);if(archive.Entries.Count is <4 or >9||archive.Entries.Sum(e=>e.Length)>1024L*1024*1024||archive.Entries.Any(e=>e.Length>512L*1024*1024)||archive.Entries.Select(e=>e.FullName).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=archive.Entries.Count)throw new InvalidDataException("Invalid or oversized car project.");
        var allowed=new HashSet<string>(new[]{"Car.json","Manifest.json","Paint.flproject","Exterior.fbx","Exterior.obj","Exterior.glb","Assembly.FBX","Layout.tsv","Report.json","Preview.flsm"},StringComparer.Ordinal);
        if(archive.Entries.Any(e=>!allowed.Contains(e.FullName))||archive.Entries.Count(e=>e.FullName.StartsWith("Exterior",StringComparison.Ordinal))!=1)throw new InvalidDataException("The car project contains unexpected files.");var metadata=archive.GetEntry("Manifest.json")??throw new InvalidDataException("Missing car manifest.");if(metadata.Length>64*1024)throw new InvalidDataException("Oversized car manifest.");Manifest manifest;using(var reader=new StreamReader(metadata.Open()))manifest=JsonSerializer.Deserialize<Manifest>(reader.ReadToEnd(),Contract.Json)??throw new InvalidDataException("Invalid car manifest.");if(manifest.Version!=1||manifest.Hashes.Count!=archive.Entries.Count-1||manifest.Hashes.Keys.Any(n=>!allowed.Contains(n)||n=="Manifest.json"))throw new InvalidDataException("Invalid car file inventory.");
        var folder=Path.Combine(workspace,"opened",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);foreach(var entry in archive.Entries.Where(e=>e.FullName!="Manifest.json")){if(!manifest.Hashes.TryGetValue(entry.FullName,out var hash)||!Regex.IsMatch(hash,"^[0-9A-F]{64}$"))throw new InvalidDataException("Missing car file hash.");var file=Path.Combine(folder,entry.FullName);entry.ExtractToFile(file);if(WorkshopService.Hash(file)!=hash)throw new InvalidDataException("A car project file was changed or damaged: "+entry.FullName);}
        var recipe=Path.Combine(folder,"Car.json");if(new FileInfo(recipe).Length>256*1024)throw new InvalidDataException("Oversized car recipe.");var project=JsonSerializer.Deserialize<VehicleAssemblyProject>(File.ReadAllText(recipe),Contract.Json)??throw new InvalidDataException("Invalid car recipe.");project.Validate(source:false);
        string Local(string name,string expected){if(name.Length==0)return "";if(name!=expected||!manifest.Hashes.ContainsKey(name))throw new InvalidDataException("Invalid car source reference.");return Path.Combine(folder,name);}
        var exterior=archive.Entries.Single(e=>e.FullName.StartsWith("Exterior",StringComparison.Ordinal)).FullName;project.ExteriorFile=Local(project.ExteriorFile,exterior);project.AssemblyFile=Local(project.AssemblyFile,"Assembly.FBX");project.BindingFile=Local(project.BindingFile,"Layout.tsv");project.ReportFile=Local(project.ReportFile,"Report.json");project.PreviewFile=Local(project.PreviewFile,"Preview.flsm");project.Paint=ProjectBundle.Open(Path.Combine(folder,"Paint.flproject"),Path.Combine(folder,"paint"));project.Id=Guid.NewGuid().ToString("N");project.Paint.FlatExteriorNormals=!project.Paint.IndependentPaintSides;project.Validate();if(WorkshopService.Hash(project.ExteriorFile)!=project.ExteriorHash)throw new InvalidDataException("The exterior source hash differs from the car recipe.");
        if(project.PreparedDesign.Length>0){var old=JsonSerializer.Deserialize<VehicleAssemblyProject>(project.PreparedDesign,Contract.Json)??throw new InvalidDataException("Invalid previous car recipe.");old.Validate(source:false);if(old.ExteriorHash!=project.ExteriorHash)throw new InvalidDataException("The previous car source does not match the bundled exterior.");old.PreparedDesign="";old.Id=project.Id;old.ExteriorFile=project.ExteriorFile;old.AssemblyFile=project.AssemblyFile;old.BindingFile=project.BindingFile;old.ReportFile=project.ReportFile;old.PreviewFile=project.PreviewFile;old.Paint=project.Paint with{CarIndex=old.DonorIndex};if(!old.Prepared)throw new InvalidDataException("The previous car recipe does not match the bundled assembly.");project.PreparedDesign=JsonSerializer.Serialize(old,Contract.Json);}
        if(project.Prepared)project.Paint.CarIndex=project.DonorIndex;VehicleAssemblyService.RememberPrepared(project);return project;
    }
}
